def find_horizontal_runs(grid):
    runs = []
    for r in range(len(grid)):
        c = 0
        while c < len(grid[0]):
            if grid[r][c] == 5:  # Pattern value
                start = c
                while c < len(grid[0]) and grid[r][c] == 5:
                    c += 1
                end = c - 1
                length = end - start + 1
                if length >= 2:  # Only meaningful runs
                    runs.append((r, start, end, length))
            else:
                c += 1
    return runs

horiz_runs = find_horizontal_runs(test_input)
print(f"Horizontal runs of 5 (length >= 2):")
for r, start, end, length in sorted(horiz_runs):
    print(f"  Row {r}: cols {start}-{end}, length {length}")

# Nowsolla vertical runs of 5
def find_vertical_runs(grid):
    runs = []
    for c in range(len(grid[0])):
        r = 0
        while r < len(grid):
            if grid[r][c] == 5:
                start = r
                while r < len(grid) and grid[r][c] == 5:
                    r += 1
                end = r - 1
                length = end - start + 1
                if length >= 2:
                    runs.append((start, c, end, length))
            else:
                r += 1
    return runs

